"""Exact replay for the bounded-deletion EC49 Hall-cut proof."""

from collections import Counter
from functools import cache, reduce
from itertools import combinations_with_replacement, product
from operator import and_
import json


def contained(mask, cut):
    return mask & ~cut == 0


def envelope(rows, size):
    return tuple(
        min(value for cut, value in rows.items() if contained(query, cut))
        for query in range(size)
    )


def least_cuts(rows, size):
    optimum = envelope(rows, size)
    return tuple(
        reduce(and_, (cut for cut, value in rows.items()
                      if contained(query, cut) and value == optimum[query]))
        for query in range(size)
    )


def initial(caps, labels, reserve):
    size = 1 << len(caps)
    rows = {
        cut: sum(cap for port, cap in enumerate(caps) if contained(1 << port, cut))
        - sum(contained(mask, cut) for mask in labels)
        for cut in range(size)
    }
    values = envelope(rows, size)
    rank = len(labels) + values[0]
    rows = {cut: value for cut, value in rows.items() if value - values[cut] < reserve}
    return rank, tuple(value - values[0] for value in values), rows


def step(rows, size, mask, deletion, reserve):
    direction = 1 if deletion else -1
    updated = {cut: value + direction * contained(mask, cut) for cut, value in rows.items()}
    values = envelope(updated, size)
    offset = values[0]
    rows = {cut: value for cut, value in updated.items() if value - values[cut] < reserve}
    return offset, tuple(value - offset for value in values), rows


@cache
def matching_rank(caps, labels):
    slots = tuple(1 << port for port, cap in enumerate(caps) for _ in range(cap))
    occupied = {0}
    for mask in labels:
        occupied |= {
            used | (1 << i)
            for used in occupied
            for i, slot in enumerate(slots)
            if mask & slot and used & (1 << i) == 0
        }
    return max(used.bit_count() for used in occupied)


@cache
def direct(caps, labels):
    rank = matching_rank(caps, labels)
    values = []
    for query in range(1 << len(caps)):
        probes = tuple(
            1 << port for port, cap in enumerate(caps) if contained(1 << port, query) for _ in range(cap)
        )
        values.append(matching_rank(caps, tuple(sorted(labels + probes))) - rank)
    return rank, tuple(values)


def replay(caps, labels, rows, values, rank, reserve, depth, checks):
    assert (rank, values) == direct(caps, labels)
    checks["matching_state_checks"] += 1
    if depth == 0:
        return
    size = 1 << len(caps)
    for mask in range(size):
        checks["insertion_steps"] += 1
        next_labels = tuple(sorted(labels + (mask,)))
        if reserve == 0:
            gain = int(values[mask] > 0)
            next_rank = rank + gain
            next_values = tuple(min(values[query], values[query | mask] - 1) + 1 - gain
                                for query in range(size))
            next_rows = {}
        else:
            offset, next_values, next_rows = step(rows, size, mask, False, reserve)
            next_rank = len(next_labels) + offset
        replay(caps, next_labels, next_rows, next_values, next_rank, reserve, depth - 1, checks)
    if reserve == 0:
        return
    for mask in sorted(set(labels)):
        copy = list(labels)
        copy.remove(mask)
        offset, next_values, next_rows = step(rows, size, mask, True, reserve - 1)
        next_rank = len(copy) + offset
        optimum = envelope(rows, size)
        delta = tuple(
            int(all(contained(mask, cut) for cut, cost in rows.items()
                    if contained(query, cut) and cost == optimum[query]))
            for query in range(size)
        )
        assert next_rank == rank - 1 + delta[0]
        assert next_values == tuple(value + shift - delta[0] for value, shift in zip(values, delta))
        checks["one_deletion_formula_checks"] += 1
        checks["deletion_steps"] += 1
        replay(caps, tuple(copy), next_rows, next_values, next_rank, reserve - 1, depth - 1, checks)


def main():
    counts = Counter()
    for caps in product(range(3), repeat=2):
        for length in range(5):
            for labels in combinations_with_replacement(range(4), length):
                _, values, rows = initial(caps, labels, 1)
                least = least_cuts(rows, 4)
                for mask in range(4):
                    _, _, next_rows = initial(caps, labels + (mask,), 1)
                    assert least_cuts(next_rows, 4) == tuple(
                        least[query | mask] if values[query | mask] == values[query] else least[query]
                        for query in range(4)
                    )
                    counts["least_cut_insertion_checks"] += 1
                for reserve in (1, 2, 3):
                    rank, values, rows = initial(caps, labels, reserve)
                    counts["initial_instances"] += 1
                    replay(caps, labels, rows, values, rank, reserve, 4, counts)

    caps = (1, 1)
    assert direct(caps, (1, 2)) == direct(caps, (1, 3)) == (2, (0, 0, 0, 0))
    assert direct(caps, (2, 2))[0] == 1 < direct(caps, (2, 3))[0] == 2
    for horizon in range(1, 25):
        left = (1,) * (horizon + 1)
        right = (2,) * horizon
        a = left + right
        b = left[:-1] + right + (3,)
        assert initial(caps, a, horizon - 1) == initial(caps, b, horizon - 1)
        for deleted in range(horizon):
            assert direct(caps, a[0:len(a) - deleted]) == direct(
                caps, b[0:len(b) - deleted - 1] + (3,)
            )
        assert direct(caps, left)[0] == 1 < direct(caps, left[:-1] + (3,))[0] == 2
        counts["sharp_horizon_instances"] += 1
    print(json.dumps(counts, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
